import { parseOpenCommChannelMessage } from "../../src/handlers/handleOpenCommChannel.js";
import { expect, it, suite } from "vitest";

const testBuffer = Buffer.from(
    "", "hex"
);

suite("OpenCommChannelMessage", () => {
    it("can be deserialized from a buffer", () => {
        const incomingRequest = parseOpenCommChannelMessage(testBuffer);
         expect(
             (
                 incomingRequest.getFieldValueByName("commId") as Buffer
             ).readInt32BE(),
         ).toBe(2883705);
         expect((incomingRequest.getFieldValueByName("riffName") as string).replace(/\x00/g, "")).toBe("race");
         expect((incomingRequest.getFieldValueByName("userId") as Buffer).readInt32BE()).toBe(21);
        });
});


